def check_partition(m):
    """
    Checks if {1, 2, ..., m} can be partitioned into three non-empty subsets X, Y, R
    such that Sum(X) = Sum(Y) = Sum(R) = T = m(m+1)/6.
    """
    if m < 3:
        return False

    total_sum = m * (m + 1) // 2
    if total_sum % 3 != 0:
        return False

    T = total_sum // 3

    # Special case verification from notes: m=3, T=2. {1, 2, 3}. Cannot make 3 non-empty sets summing to 2.
    if m == 3:
        return False

    elements = list(range(1, m + 1))

    def find_subset(current_set, remaining_elements, target_sum, required_count):
        """
        Recursively tries to find 'required_count' non-empty subsets summing to target_sum
        from remaining_elements.

        Returns True if successful, False otherwise.
        """
        if required_count == 0:
            # Successfully found all required subsets
            return True

        # Optimization: If the smallest remaining element is greater than T, we fail.
        if not remaining_elements or remaining_elements[0] > target_sum:
            return False

        # Use backtracking to find one subset S_i
        def backtrack_subset(index, current_sum, current_subset):
            if current_sum == target_sum:
                # Found one subset. Recurse to find the next required subset
                new_remaining = [e for e in remaining_elements if e not in current_subset]
                # Ensure the found subset is non-empty (guaranteed if T > 0, which is true for m >= 4)
                return find_subset(current_subset, new_remaining, target_sum, required_count - 1)

            if current_sum > target_sum or index == len(remaining_elements):
                return False

            # Standard subset sum search
            # Include element at index
            if backtrack_subset(index + 1, current_sum + remaining_elements[index], current_subset + [remaining_elements[index]]):
                return True

            # Exclude element at index
            if backtrack_subset(index + 1, current_sum, current_subset):
                return True

            return False

        # Start search for the next subset (S_i) using all remaining elements
        # We pass the current set found so far (though it's empty initially for the first call)
        # The search is constrained by remaining_elements
        return backtrack_subset(0, 0, [])

    # We need to find 3 non-empty subsets X, Y, R.
    return find_subset([], elements, T, 3)


# Search for m <= 100 such that m != 1 (mod 3)
solutions = []
for m in range(1, 101):
    # Necessary condition check: m != 1 (mod 3)
    if m % 3 == 1:
        continue

    if check_partition(m):
        solutions.append(m)

print(f"Total solutions found (m <= 100, m != 1 mod 3): {len(solutions)}")
print(f"List of solutions: {solutions}")
